<script setup>
import { computed } from 'vue'
import ToolActivityIcon from './ToolActivityIcon.vue'
import StableSurface from './StableSurface.vue'
import {toolIcons} from '../tool-icons.mjs'
import { activityPhase,activityPurpose,terminalPhase } from '../tool-activity.mjs'
import { isDesktop } from '../local-resources.mjs'
import { appUrl } from '../app-url.mjs'
const props=defineProps({line:Object,pinned:Boolean,paused:Boolean,entering:Boolean,terminalTask:Object,images:{type:Array,default:()=>[]},resourceUrl:Function,resourceHeight:Function,downloadName:Function})
const emit=defineEmits(['observe','details','resource','entered'])
function observe(){if(resources.value.length||props.line.toolName==='image_create'&&!props.line.live)emit('details',props.line);else emit('observe',props.line)}
const phase=computed(()=>['terminal_run','terminal_control'].includes(props.line.toolName)?terminalPhase(props.terminalTask?{...props.line,observation:{...props.line.observation,status:props.terminalTask.status,exit_code:props.terminalTask.exitCode}}:props.line):activityPhase(props.line)),purpose=computed(()=>activityPurpose(props.line))
const pendingImage=computed(()=>props.line.toolName==='image_create'&&!props.images.length)
const resources=computed(()=>props.line.resources||[])
const isPlugin=computed(()=>!toolIcons[props.line.toolName])
const pendingPlugin=computed(()=>isPlugin.value&&!resources.value.length&&['generating','running','queued'].includes(phase.value))
const pendingCount=computed(()=>Math.max(1,Math.min(4,Number(props.line.activity?.input?.n)||1)))
const resourceAction=isDesktop()?'打开所在文件夹':'下载'
function sizeLabel(value){const n=Number(value);if(!Number.isFinite(n)||n<0)return '';return n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`}
const fallbackDownloadName=(image,index)=>`${image.label||`image-${index+1}`}.${image.mimeType==='image/jpeg'?'jpg':image.mimeType==='image/webp'?'webp':'png'}`
</script>
<template><div :class="['tool-activity-entry',{'is-entering':entering}]" :data-tool="line.toolName" :data-phase="phase">
<button class="tool-activity-row" type="button" :aria-pressed="pinned" :title="purpose" @click="observe" @animationend="$event.animationName==='activity-text-enter' && $emit('entered')"><ToolActivityIcon :name="line.toolName" :phase="phase" :paused="paused"/><span class="activity-purpose">{{purpose}}</span><svg v-if="pinned" class="activity-pin" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M8 3h8l-1 7 4 4v2H5v-2l4-4zM12 16v6"/></svg></button>
<StableSurface v-if="line.toolName==='image_create'"><div class="activity-delivery image-delivery">
<template v-if="pendingImage"><div v-for="slot in pendingCount" :key="slot" class="activity-image-card" :aria-busy="line.live"><div class="activity-image-placeholder"><ToolActivityIcon name="image_create" :phase="phase" :paused="paused"/></div><div class="activity-delivery-caption"><span class="activity-skeleton"></span><button v-if="phase==='failed'||phase==='interrupted'" class="activity-action" title="详情" aria-label="详情" @click="$emit('details',line)"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/></svg></button></div></div></template>
<figure v-for="(image,index) in images" :key="image.imageId||image.previewUrl||index" class="activity-image-card"><button v-if="image.available!==false && image.previewUrl" class="activity-image-trigger image-preview-trigger" :data-preview-src="appUrl(image.originalUrl||image.previewUrl)" :aria-label="`预览 ${image.label||'图片'}`"><img :src="appUrl(image.previewUrl)" :alt="image.label||'图片'" loading="lazy"/></button><div v-else class="activity-image-placeholder"><ToolActivityIcon name="image_create" phase="failed"/></div><figcaption class="activity-delivery-caption"><span>{{image.label||line.activity?.input?.semanticName}}</span><small v-if="image.sizeBytes!==undefined" class="delivery-file-size">{{sizeLabel(image.sizeBytes)}}</small><a v-if="image.previewUrl" class="activity-action resource-text-action" :href="appUrl(image.originalUrl||image.previewUrl)" :download="downloadName?downloadName(image,index):fallbackDownloadName(image,index)" :aria-label="resourceAction" :title="resourceAction" data-resource-download="true"><span v-if="!isDesktop()">{{resourceAction}}</span><svg viewBox="0 0 24 24"><path :d="isDesktop()?'M3 7V5h6l2 2h10v13H3V7Zm0 3h18':'M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4'"/></svg></a><button class="activity-action" aria-label="详情" title="详情" @click="$emit('details',line)"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/></svg></button></figcaption></figure>
</div></StableSurface>
<StableSurface v-if="isPlugin||resources.length"><div v-if="resources.length||pendingPlugin" class="activity-delivery plugin-delivery">
<div v-if="pendingPlugin" :class="['activity-plugin-placeholder',{'is-editor':line.toolName==='open_xhs_artifact_editor','is-video':line.toolName==='expose_videos'}]"><ToolActivityIcon name="plugin" :phase="phase" :paused="paused"/></div>
<template v-for="resource in resources" :key="resource.url">
<iframe v-if="['embed','iframe','artifact'].includes(resource.kind)" :src="resourceUrl?resourceUrl(resource):appUrl(resource.url)" :title="resource.label||'插件内容'" :style="{height:(resourceHeight?resourceHeight(resource):640)+'px'}" allow="fullscreen" allowfullscreen loading="lazy"></iframe>
<video v-else-if="resource.kind==='video'" :src="resourceUrl?resourceUrl(resource):appUrl(resource.url)" controls preload="metadata"></video>
<div v-else class="activity-file-card"><ToolActivityIcon name="plugin" :phase="phase"/><span>{{resource.downloadName||resource.label||'文件'}}</span><small v-if="resource.sizeBytes!==undefined" class="delivery-file-size">{{sizeLabel(resource.sizeBytes)}}</small><a class="activity-action resource-text-action" :href="appUrl(resource.url)" :download="resource.downloadName||undefined" data-resource-download="true" :data-resource-expires-at="resource.expiresAt" :title="resourceAction" :aria-label="resourceAction" @click="$emit('resource',$event,resource)"><span v-if="!isDesktop()">{{resourceAction}}</span><svg viewBox="0 0 24 24"><path :d="isDesktop()?'M3 7V5h6l2 2h10v13H3V7Zm0 3h18':'M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4'"/></svg></a></div>
</template></div></StableSurface>
</div></template>
<style>
.activity-action.resource-text-action{display:inline-flex;width:auto;gap:5px;text-decoration:none;font-size:calc(11px * var(--appearance-ui-scale, 1))}.delivery-file-size{font-size:calc(10px * var(--appearance-ui-scale, 1));color:var(--muted);white-space:nowrap;font-variant-numeric:tabular-nums}
.tool-activity-entry{min-width:0;color:var(--text)}.tool-activity-row{display:flex;align-items:center;gap:6px;min-height:26px;padding:3px 0 3px var(--activity-icon-inset,30px);border:0;background:transparent;color:inherit;text-align:left;max-width:100%;cursor:pointer;font-family:var(--appearance-ui-font, inherit);font-size:calc(12px * var(--appearance-ui-scale, 1));line-height:20px}.tool-activity-row>.activity-icon{width:16px;height:16px;stroke-width:2.4}.activity-purpose{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.tool-activity-entry.is-entering .tool-activity-row>.activity-icon{animation:activity-icon-enter 480ms cubic-bezier(.16,1,.3,1) both}.tool-activity-entry.is-entering .activity-purpose{animation:activity-text-enter 460ms ease 100ms both}.activity-pin{width:13px;height:16px;flex-shrink:0;color:var(--purple);transform-origin:50% 90%;animation:activity-pin-strike 520ms linear both}.activity-delivery{margin:5px 0 12px var(--activity-content-inset,30px);max-width:720px}.image-delivery{display:flex;gap:16px;flex-wrap:wrap}.activity-image-card{margin:0;width:320px;max-width:100%;border:var(--appearance-border-width, 1px) solid color-mix(in srgb,currentColor 17%,transparent);border-radius:var(--appearance-radius, 7px);overflow:hidden;background:color-mix(in srgb,currentColor 3%,transparent)}.activity-image-trigger{display:block;width:100%;padding:8px;border:0;background:none;cursor:zoom-in}.activity-image-trigger img{display:block;width:100%;height:200px;object-fit:contain}.activity-image-placeholder{height:216px;display:grid;place-items:center}.activity-delivery-caption{display:flex;align-items:center;gap:7px;padding:8px 10px;height:45px;border-top:var(--appearance-border-width, 1px) solid color-mix(in srgb,currentColor 12%,transparent);font-size:calc(12px * var(--appearance-ui-scale, 1))}.activity-delivery-caption>span{min-width:0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.activity-action{display:inline-grid;place-items:center;flex-shrink:0;width:28px;height:28px;border:0;background:none;color:inherit;padding:4px;cursor:pointer}.activity-action svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.activity-action:hover{color:var(--purple)}.activity-skeleton{height:8px;max-width:140px;border-radius:var(--appearance-radius, 3px);background:color-mix(in srgb,currentColor 10%,transparent)}.activity-file-card{display:flex;align-items:center;gap:10px;min-height:50px;width:fit-content;max-width:100%;padding:8px 12px;border:var(--appearance-border-width, 1px) solid color-mix(in srgb,currentColor 17%,transparent);border-radius:var(--appearance-radius, 5px)}.activity-file-card>span{overflow-wrap:anywhere;min-width:0;font-size:calc(12px * var(--appearance-ui-scale, 1))}.plugin-delivery{display:grid;gap:12px}.plugin-delivery iframe{width:100%;border:var(--appearance-border-width, 1px) solid color-mix(in srgb,currentColor 15%,transparent);border-radius:var(--appearance-radius, 7px)}.plugin-delivery video{width:100%;aspect-ratio:16/9;border-radius:var(--appearance-radius, 7px);background:#111}.activity-plugin-placeholder{min-height:50px;display:flex;align-items:center;padding:8px 12px}.activity-plugin-placeholder.is-editor{height:640px}.activity-plugin-placeholder.is-video{aspect-ratio:16/9}.tool-activity-row:focus-visible,.activity-action:focus-visible{outline:1px solid var(--purple)}@keyframes activity-icon-enter{0%{opacity:0;transform:translateX(-26px) scale(.7)}65%{transform:translateX(2px) scale(1.08)}100%{opacity:1;transform:none}}@keyframes activity-text-enter{from{opacity:0;transform:translateX(22px)}to{opacity:1;transform:none}}@keyframes activity-pin-strike{0%{opacity:0;transform:translate(5px,-15px) rotate(28deg)}24%{opacity:1;transform:translate(2px,-10px) rotate(18deg)}42%,54%{transform:translate(0,3px) rotate(-7deg) scale(.9,1.1)}70%{transform:translate(0,-3px) rotate(6deg)}84%{transform:translate(0,1px) rotate(-3deg)}100%{transform:none}}@media(prefers-reduced-motion:reduce){.activity-pin,.tool-activity-entry.is-entering .tool-activity-row>.activity-icon,.tool-activity-entry.is-entering .activity-purpose{animation:none}}@media(max-width:600px){.activity-delivery{margin-left:var(--activity-content-inset,30px)}.activity-image-trigger img{height:158px}.activity-image-placeholder{height:174px}}
</style>
